INSERT INTO feature VALUES('domhringr-effect-space','effects','domhringr''s effect space as theories','effect-rows','implemented','notable',NULL,'What a domhringr stage performs besides its session''s moves, as nine theories: Store, Journal, Judge, Witness, Clock, Random, Trace, Fail and Cancel, each with its operations and first-order laws and stating what it commutes with. The laws that sequence one operation after another, a put''s and a lookup''s idempotence and each commutation past an operation answering a value, are written over continuations, the value an operation answers bound by `bind x . …` and named only at a port of its sort.',NULL,'corpus/model/effects/domhringr.gandr corpus/pathological/effects/domhringr.gandr','corpus/model/effects/domhringr.gandr',NULL);
